    "code": "\n# a simulated walk for the checks: a pedestrian at 1.4 m/s, 30 frames per second, seen through the camera with 1.5 px box noise\nrng = np.random.default_rng(0)\nHinv = np.linalg.inv(H)\ndef to_image(g):\n    p = cv2.perspectiveTransform(np.float32([g]).reshape(-1, 1, 2), Hinv)\n    return p.reshape(2)\ndef walk(start, vel, T):\n    boxes = []\n    for t in range(T):\n        g = np.array(start) + np.array(vel) * t / 30\n        f = to_image(g) + rng.normal(0, 1.5, 2)\n        boxes.append(np.array([f[0] - 8, f[1] - 40, f[0] + 8, f[1]]))\n    return boxes\n\nmeter = SpeedMeter(H, fps=30, window=1.0)\nnaive = SpeedMeter(H, fps=30, window=1 / 30)\nfor name, start in ((\"near\", (6, 2)), (\"far\", (6, 20))):\n    boxes = walk(start, (1.4, 0), 150)\n    sp_w = [meter.update(name, b)[0] for b in boxes]\n    sp_n = [naive.update(name, b)[0] for b in boxes]\n    sp_w = np.array([v for v in sp_w if v is not None]); sp_n = np.array([v for v in sp_n if v is not None])\n    print(name, \": frame to frame\", round(float(sp_n.mean()), 2), \"+-\", round(float(sp_n.std()), 2), \"  one-second window\", round(float(sp_w.mean()), 2), \"+-\", round(float(sp_w.std()), 2))\n",
